from sympy import symbols, sympify, factorial, expand

x = symbols("x")

def series_of(name, u, count):
    if name == "exp":
        return sum(u**k / factorial(k) for k in range(count))
    if name == "sin":
        return sum((-1)**k * u**(2*k + 1) / factorial(2*k + 1) for k in range(count))
    return sum((-1)**k * u**(2*k) / factorial(2*k) for k in range(count))

total = int(input())
for problem in range(total):
    name = input()
    u_text = input()
    count = int(input())
    point_text = input()
    u = sympify(u_text)
    point = sympify(point_text)
    T = expand(series_of(name, u, count))
    f = sympify(f"{name}({u_text})")
    print(f"Problem {problem + 1}: {name}(u) with u = {u_text}, {count} terms")
    print(f"  {T}")
    print(f"  at x = {point_text}: {float(T.subs(x, point)):.8f}, true {float(f.subs(x, point)):.8f}")
